 developers:['Для разработчиков','For developers','Pentru dezvoltatori'],docs:['Документация','Documentation','Documentație'],sandbox:['Тестовая среда','Test environment','Mediu de test'],search:['Поиск по документации…','Search documentation…','Caută în documentație…'],searchLabel:['Поиск','Search','Căutare'],searchEmpty:['Ничего не найдено. Попробуйте «возврат», «Order» или «Hash».','No results. Try “refund”, “Order” or “Hash”.','Niciun rezultat. Încercați „rambursare”, „Order” sau „Hash”.'],menu:['Открыть навигацию','Open navigation','Deschide navigarea'],close:['Закрыть','Close','Închide'],skip:['Перейти к содержимому','Skip to content','Sari la conținut'],language:['Язык','Language','Limbă'],
